using UnityEngine;

public class SpikeDecorationBase : ObstacleDecoration
{
	private bool autoSpikes;

	public SpikeDecorationBase()
	{
		dimensions = new GridDimensions(4, 40, 4, 40);
		prefab = ChaosBundle.Get("Assets/Prefabs/Environment/FloorSpike.prefab");
		spawnChance = 0.005f;
		spawnPrefab = true;
		spawnPrefabOnEveryTile = true;
		prefabWorldOffsetX = 0.5f;
		prefabWorldOffsetY = 1f;
		minDupeDistance = 20f;
		placementTests.Add(AdjTileTest.NoObstacleSurround2);
	}

	public override void Place(TileGrid tileGrid, int rowOrigin, int colOrigin, Transform parentTrans = null, Room room = null)
	{
		if (Random.value > 0.5f)
		{
			autoSpikes = true;
		}
		base.Place(tileGrid, rowOrigin, colOrigin, parentTrans, room);
	}

	public override GameObject SpawnPrefab(TileGrid tileGrid, int rowOrigin, int colOrigin, int rowOffset = 0, int colOffset = 0, Transform parentTrans = null, Room room = null)
	{
		GameObject gameObject = base.SpawnPrefab(tileGrid, rowOrigin, colOrigin, rowOffset, colOffset, parentTrans, room);
		FloorSpike component = gameObject.GetComponent<FloorSpike>();
		if (autoSpikes)
		{
			component.mode = FloorSpike.FloorSpikeMode.Auto;
		}
		return gameObject;
	}
}

