	{
		if (!tileGrid.IsValidTile(row, col))
		{
			return false;
		}
		if (tileLayerNames == null || tileLayerNames.Length == 0 || tileGrid[row, col].layers == null)
		{
			return tileGrid[row, col].hasDoodad == hasDoodad;
		}
		for (int i = 0; i < tileLayerNames.Length; i++)
		{
			if (tileGrid[row, col].layers[tileLayerNames[i]].hasDoodad != hasDoodad)
			{
				return false;
			}
		}
		return true;
	}
