	{
		int num = base.TerrainTypeToTileSetID(terrain, tileRow, tileCol, tileGrid);
		if (lowerWallTiles.Contains(num) && tileGrid.IsValidTile(tileRow + 1, tileCol))
		{
			Tile tile = tileGrid[tileRow + 1, tileCol];
			if (tile.pitOverrideType != Tile.FloorType.None)
			{
				return num;
			}
			if ((tileGrid.IsValidTile(tileRow + 1, tileCol + 1) && tileGrid[tileRow + 1, tileCol + 1].terrain == Tile.TerrainType.Pit) || (tileGrid.IsValidTile(tileRow + 1, tileCol - 1) && tileGrid[tileRow + 1, tileCol - 1].terrain == Tile.TerrainType.Pit))
			{
				return num;
			}
			int tileSetID = 0;
			switch (num)
			{
